import type { BankQuestion } from "@/lib/bank";

/** OOP with C++ and Java (Programming): 97 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cs-oops-cpp-java-1","question":"Which OOP principle bundles data with the methods that act on it and hides the internal state behind an interface?","options":["Encapsulation","Polymorphism","Inheritance","Abstraction through interfaces only"],"answer":0,"explanation":"Encapsulation keeps fields private and exposes behaviour through methods, so the object controls how its state changes. Inheritance reuses code; polymorphism lets one call behave differently by type.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-oops-cpp-java-2","question":"In Java, which keyword makes one class inherit from another class?","options":["inherits","extends","implements","super"],"answer":1,"explanation":"class B extends A makes B a subclass of A. implements is used for interfaces; super refers to the parent inside the subclass.","difficulty":"easy","source":"Wipro · Capgemini pattern"},
  {"id":"cs-oops-cpp-java-3","question":"What is the return type of a C++ constructor?","options":["int","The class type","It has no return type, not even void","void"],"answer":2,"explanation":"A constructor is declared with the class name and no return type at all; writing void before it makes it an ordinary (badly named) function instead.","difficulty":"easy","source":"Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-4","question":"Every Java class that declares no superclass implicitly extends:","options":["java.lang.System","Nothing","java.lang.Class","java.lang.Object"],"answer":3,"explanation":"Object is the root of the Java class hierarchy, which is why every object has equals, hashCode and toString.","difficulty":"easy","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-oops-cpp-java-5", "question": "In C++, members of a class declared without any access specifier are:", "options": ["private", "Accessible within the same file", "public", "protected"], "answer": 0, "explanation": "class members default to private, while struct members default to public. That is the only real difference between the two keywords (default inheritance follows the same rule).", "difficulty": "easy", "source": "IBM · Deloitte pattern"},
  {"id": "cs-oops-cpp-java-6", "question": "Which statement about Java String objects is correct?", "options": ["They are primitive types", "They are immutable: methods like toUpperCase return a new String", "They are mutable but thread-unsafe", "They can be changed in place with setCharAt"], "answer": 1, "explanation": "A String's characters never change after creation; every modifying-looking method returns a new object. setCharAt belongs to StringBuilder, the mutable alternative.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-oops-cpp-java-7", "question": "What is printed?\n```java\nString s = \"ab\";\ns.concat(\"cd\");\ns.toUpperCase();\nSystem.out.print(s);\n```", "options": ["abcd", "ABCD", "ab", "AB"], "answer": 2, "explanation": "Strings are immutable: concat and toUpperCase return new strings, and both results are thrown away because they are not assigned. s still refers to \"ab\".", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-oops-cpp-java-8", "question": "Which pairing is correct?", "options": ["Both are resolved at run time", "Both are resolved at compile time", "Overloading is resolved at compile time; overriding is resolved at run time", "Overloading is resolved at run time; overriding is resolved at compile time"], "answer": 2, "explanation": "The compiler picks an overload from the argument types it can see (static polymorphism). Which override runs depends on the actual object at run time (dynamic dispatch).", "difficulty": "moderate", "source": "Wipro · Capgemini pattern"},
  {"id":"cs-oops-cpp-java-9","question":"Which of these operators cannot be overloaded in C++?","options":["+=","[]","()","::"],"answer":3,"explanation":"The scope resolution operator ::, member access ., .*, the conditional ?: and sizeof cannot be overloaded. [], () and += are commonly overloaded.","difficulty":"moderate","source":"Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-10","question":"A variable declared inside a Java interface is implicitly:","options":["public static final","private static","public and per-object","protected final"],"answer":0,"explanation":"Interface fields are constants: public, static and final whether you write those words or not, and they must be initialised where they are declared.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-oops-cpp-java-11","question":"What is printed?\n```cpp\nclass A {\npublic:\n    A()  { cout << \"A\"; }\n    ~A() { cout << \"a\"; }\n};\nclass B : public A {\npublic:\n    B()  { cout << \"B\"; }\n    ~B() { cout << \"b\"; }\n};\nint main() { B obj; }\n```","options":["BAba","ABba","ABab","BAab"],"answer":1,"explanation":"Construction runs base first, then derived: A then B. Destruction runs in exactly the reverse order: ~B then ~A. So ABba.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-oops-cpp-java-12","question":"What is printed?\n```java\nclass C {\n    static int n = 0;\n    C() { n++; }\n}\n// in main:\nfor (int i = 0; i < 3; i++) new C();\nC c = new C();\nSystem.out.print(c.n);\n```","options":["3","1","4","0"],"answer":2,"explanation":"n is static, so one copy is shared by all objects and every constructor call adds to it: 3 objects in the loop plus c makes 4. Reading it through c.n still reads the shared field.","difficulty":"moderate","source":"Wipro · Capgemini pattern"},
  {"id": "cs-oops-cpp-java-13", "question": "In Java, final applied to a class, a method and a variable means, respectively:", "options": ["Cannot be instantiated; cannot be overridden; cannot be reassigned", "Cannot be instantiated; cannot be overloaded; cannot be read", "Cannot be subclassed; cannot be overloaded; must be static", "Cannot be subclassed; cannot be overridden; cannot be reassigned"], "answer": 3, "explanation": "A final class (like String) has no subclasses, a final method cannot be overridden (it can still be overloaded), and a final variable is assigned exactly once. Preventing instantiation is what abstract or a private constructor does.", "difficulty": "moderate", "source": "Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-14","question":"What is printed?\n```java\nList<Integer> list = new ArrayList<>();\nlist.add(1);\nlist.add(2);\nlist.add(1, 5);\nSystem.out.print(list);\n```","options":["[1, 5, 2]","[1, 2, 1, 5]","[1, 2, 5]","[5, 2]"],"answer":0,"explanation":"add(index, element) inserts 5 at index 1 and shifts the later elements right, so [1, 2] becomes [1, 5, 2]. It neither replaces (that is set) nor appends.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-oops-cpp-java-15","question":"What is printed?\n```java\nSet<String> s = new HashSet<>();\ns.add(\"a\");\ns.add(\"b\");\ns.add(\"a\");\nSystem.out.print(s.size() + \" \" + s.add(\"b\"));\n```","options":["3 false","2 false","2 true","3 true"],"answer":1,"explanation":"A Set keeps no duplicates, so the second \"a\" is ignored and the size is 2. add returns false when the element is already present, as it is for \"b\".","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id": "cs-oops-cpp-java-16", "question": "What is printed?\n```java\ntry {\n    System.out.print(\"T\");\n    throw new RuntimeException();\n} catch (Exception e) {\n    System.out.print(\"C\");\n} finally {\n    System.out.print(\"F\");\n}\n```", "options": ["TCF", "TC", "TF", "TFC"], "answer": 0, "explanation": "T prints, the exception is thrown, the catch for Exception handles it (C), and finally always runs last (F).", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-oops-cpp-java-17", "question": "Why must a C++ copy constructor take its parameter by reference (A(const A &other)) rather than by value?", "options": ["By value would make the object const", "References are faster but by value would also work", "Passing by value would itself call the copy constructor, recursing without end", "The compiler cannot copy private members by value"], "answer": 2, "explanation": "To pass an A by value the compiler must copy it, which means calling the copy constructor, which needs another copy, and so on forever. The language therefore rejects A(A other).", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-18", "question": "What is printed?\n```java\nSystem.out.print(\"placement\".substring(2, 5) + \"placement\".indexOf('e'));\n```", "options": ["ace6", "acem4", "lac4", "ace4"], "answer": 3, "explanation": "Indices: p0 l1 a2 c3 e4 m5 e6 n7 t8. substring(2, 5) takes indices 2 to 4 (end excluded): \"ace\". indexOf('e') gives the first e, at 4.", "difficulty": "moderate", "source": "Wipro · Capgemini pattern"},
  {"id": "cs-oops-cpp-java-19", "question": "What is the time complexity of get(i) on a Java ArrayList and on a LinkedList?", "options": ["O(1) and O(n)", "O(1) and O(1)", "O(log n) and O(n)", "O(n) and O(1)"], "answer": 0, "explanation": "ArrayList is backed by an array, so it jumps straight to index i. LinkedList must walk node by node from the nearer end, which is O(n).", "difficulty": "moderate", "source": "Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-20","question":"In C++, what does new do that malloc does not?","options":["It never fails","It calls the constructor of the object it allocates","It frees the memory automatically","It allocates on the stack instead of the heap"],"answer":1,"explanation":"new allocates memory and then runs the constructor (delete runs the destructor before freeing). malloc only returns raw bytes. new throws std::bad_alloc on failure by default rather than returning NULL.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-oops-cpp-java-21", "question": "What is printed?\n```java\nclass A {\n    void show() { System.out.print(\"A\"); }\n}\nclass B extends A {\n    void show() { super.show(); System.out.print(\"B\"); }\n}\nclass C extends B {\n    void show() { System.out.print(\"C\"); super.show(); }\n}\n// in main:\nA obj = new C();\nobj.show();\n```", "options": ["C", "CBA", "ABC", "CAB"], "answer": 3, "explanation": "The object is a C, so C.show runs: it prints C, then calls B.show, which calls A.show (A) before printing B. Result CAB.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-22","question":"What is printed?\n```cpp\nclass Base {\npublic:\n    void show()          { cout << \"B1\"; }\n    virtual void vshow() { cout << \"B2\"; }\n};\nclass Derived : public Base {\npublic:\n    void show()  { cout << \"D1\"; }\n    void vshow() { cout << \"D2\"; }\n};\nint main() {\n    Base *b = new Derived;\n    b->show();\n    b->vshow();\n}\n```","options":["B1B2","D1B2","B1D2","D1D2"],"answer":2,"explanation":"show is not virtual, so the call is bound at compile time by the pointer type Base*: B1. vshow is virtual, so the call goes through the vtable to the actual object, a Derived: D2.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-23", "question": "In C++, Base has a non-virtual destructor and Derived : public Base owns a heap buffer freed in ~Derived. What happens on: Base *p = new Derived; delete p; ?", "options": ["Compilation error", "Only ~Derived runs", "Undefined behaviour; in practice ~Derived is skipped and the buffer leaks", "Both destructors run, Derived first"], "answer": 2, "explanation": "Deleting a derived object through a base pointer whose destructor is not virtual is undefined; typically only ~Base runs, so the derived part is never cleaned up. Any class meant to be a polymorphic base needs a virtual destructor.", "difficulty": "hard", "source": "Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-24","question":"What is printed?\n```java\nString a = \"hi\";\nString b = \"hi\";\nString c = new String(\"hi\");\nSystem.out.print((a == b) + \" \" + (a == c) + \" \" + a.equals(c));\n```","options":["true false false","false false true","true true true","true false true"],"answer":3,"explanation":"Equal string literals share one object from the string pool, so a == b is true. new String creates a separate object, so a == c compares different references (false). equals compares characters (true).","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-oops-cpp-java-25","question":"What is printed?\n```java\nSystem.out.print('a' + 1);\nSystem.out.print(\" \");\nSystem.out.print(\"\" + 'a' + 1);\n```","options":["98 a1","a1 a1","b a1","98 98"],"answer":0,"explanation":"'a' + 1 is char + int, which is numeric addition: 97 + 1 = 98. In \"\" + 'a' + 1 the left operand is already a String, so each + concatenates: \"a\" then \"a1\".","difficulty":"hard","source":"Wipro · Capgemini pattern"},
  {"id": "cs-oops-cpp-java-26", "question": "What is printed?\n```cpp\nvoid f(int)    { cout << \"int \"; }\nvoid f(double) { cout << \"double \"; }\nint main() {\n    f('a');\n    f(2.5f);\n}\n```", "options": ["double double", "int double", "int int", "Compilation error: ambiguous call"], "answer": 1, "explanation": "char to int is an integral promotion, which beats the char-to-double conversion, so f('a') picks f(int). float to double is a floating-point promotion, which beats float-to-int, so f(2.5f) picks f(double).", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-27", "question": "What is printed?\n```cpp\nstruct A {\n    A()          { cout << \"C\"; }\n    A(const A &) { cout << \"K\"; }\n    ~A()         { cout << \"D\"; }\n};\nvoid f(A a) { }\nint main() {\n    A x;\n    f(x);\n}\n```", "options": ["CKDKD", "CKD", "CKDD", "CDD"], "answer": 2, "explanation": "A x runs the default constructor (C). Passing x by value copy-constructs the parameter (K), which is destroyed when the call ends (D). x is destroyed at the end of main (D).", "difficulty": "hard", "source": "Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-28","question":"What is printed?\n```cpp\nclass A {\npublic:\n    static int count;\n    A()  { count++; }\n    ~A() { count--; }\n};\nint A::count = 0;\nint main() {\n    A a, b;\n    { A c; cout << A::count; }\n    cout << A::count;\n}\n```","options":["33","31","32","22"],"answer":2,"explanation":"The one static counter is shared: a and b make it 2, c makes it 3 and that is printed. Leaving the inner block destroys c, bringing it back to 2.","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-oops-cpp-java-29","question":"Which line fails to compile?\n```cpp\nstruct Shape  { virtual double area() = 0; };\nstruct Circle : Shape { };\nstruct Square : Shape { double area() override { return 1; } };\n```","options":["Shape *p = new Square;","Shape *q = nullptr;","Square s;","Circle c;"],"answer":3,"explanation":"A class with a pure virtual function is abstract and cannot be instantiated. Circle does not override area, so it inherits the pure virtual function and stays abstract. Pointers to an abstract type are fine.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-30", "question": "class D : private B { ... }; where B has public int x, protected int y and private int z. Which is correct?", "options": ["Inside D's member functions x, y and z are accessible", "None of x, y, z is accessible inside D", "x stays public in D, so main can use d.x", "Inside D's member functions x and y are accessible, but main cannot access x through a D object"], "answer": 3, "explanation": "Private inheritance turns B's public and protected members into private members of D: usable inside D, hidden from outside. B's private z is never accessible to a derived class.", "difficulty": "hard", "source": "IBM · Deloitte pattern"},
  {"id":"cs-oops-cpp-java-31","question":"Which of these is a checked exception in Java?","options":["IOException","ArrayIndexOutOfBoundsException","ArithmeticException","NullPointerException"],"answer":0,"explanation":"Checked exceptions extend Exception but not RuntimeException, and the compiler forces you to catch or declare them; IOException is one. The other three extend RuntimeException and are unchecked.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-oops-cpp-java-32","question":"A parent class declares protected void run(). Which overriding declaration in a subclass compiles?","options":["private void run()","public void run()","void run()","protected int run()"],"answer":1,"explanation":"An override may keep or widen access but never narrow it: protected can become public, but not package-private or private. Changing the return type from void to int is not a valid override either.","difficulty":"hard","source":"Wipro · Capgemini pattern"},
  {"id": "cs-oops-cpp-java-33", "question": "Parent declares void read() throws IOException. Which override in a subclass compiles?", "options": ["void read() throws Throwable", "void read() throws Exception", "void read() throws FileNotFoundException", "void read() throws IOException, SQLException"], "answer": 2, "explanation": "An overriding method may throw the same checked exceptions, narrower ones (FileNotFoundException is a subclass of IOException) or none. It may not add broader or new checked exceptions such as Exception or SQLException.", "difficulty": "hard", "source": "Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-34","question":"What is printed?\n```java\nSet<String> t = new TreeSet<>(List.of(\"apple\", \"Banana\", \"cherry\"));\nSystem.out.print(t);\n```","options":["[apple, Banana, cherry]","[cherry, Banana, apple]","[apple, cherry, Banana]","[Banana, apple, cherry]"],"answer":3,"explanation":"TreeSet sorts by String's natural order, which compares character codes. Uppercase letters (65–90) come before lowercase (97–122), so Banana sorts first.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-35", "question": "What happens when this Java code is compiled?\n```java\nclass P { P(int x) { } }\nclass C extends P { C() { } }\n```", "options": ["Compilation error: C() implicitly calls super(), and P has no no-argument constructor", "It compiles; Java adds P() automatically", "It compiles but throws an error when a C is created", "It compiles because C's constructor is empty"], "answer": 0, "explanation": "Every constructor starts with super(...) and the compiler inserts super() if you write nothing. Since P declares a constructor, no default P() exists, so C() must call super(someInt) explicitly.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-oops-cpp-java-36","question":"What is printed?\n```java\n// static methods of the main class:\nstatic void f(int... a)      { System.out.print(\"V\"); }\nstatic void f(int a, int b)   { System.out.print(\"F\"); }\n// in main:\nf(1, 2);\nf(1, 2, 3);\n```","options":["Compilation error: ambiguous call","FV","VV","FF"],"answer":1,"explanation":"Overload resolution tries methods without varargs first, so f(1, 2) matches f(int, int) exactly: F. Only f(int...) can take three arguments: V.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-37","question":"Which member function fails to compile?\n```cpp\nclass C {\n    int a = 0;\n    mutable int hits = 0;\npublic:\n    int get() const     { hits++; return a; }\n    void set(int v) const { a = v; }\n    void reset()        { a = 0; hits = 0; }\n    int peek() const    { return a + hits; }\n};\n```","options":["reset","get","set","peek"],"answer":2,"explanation":"A const member function treats the object as const, so it cannot assign to ordinary members: set fails. get may change hits only because hits is mutable. reset is not const, and peek only reads.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-oops-cpp-java-38","question":"Which C++ operator can be overloaded only as a non-static member function, never as a free function?","options":["==","+","<<","= (assignment)"],"answer":3,"explanation":"Assignment =, subscript [], call () and member access -> must be members. +, << and == are often written as free (friend) functions so that the left operand need not be the class type.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-39","question":"What is printed?\n```java\nList<Integer> l = Arrays.asList(1, 2, 3);\ntry {\n    l.set(0, 9);\n    System.out.print(l);\n    l.add(4);\n} catch (UnsupportedOperationException e) {\n    System.out.print(\" U\");\n}\n```","options":["[9, 2, 3] U","U","[9, 2, 3, 4]","[9, 2, 3]"],"answer":0,"explanation":"Arrays.asList returns a fixed-size list backed by the array: set works because it does not change the size, but add throws UnsupportedOperationException. So the list prints, then U.","difficulty":"hard","source":"Accenture · Cognizant pattern"},
  {"id":"cs-oops-cpp-java-40","question":"What is printed?\n```java\nMap<String, Integer> m = new HashMap<>();\nSystem.out.print(m.put(\"a\", 1));\nSystem.out.print(\" \" + m.put(\"a\", 2));\nSystem.out.print(\" \" + m.size());\n```","options":["1 2 2","null 1 1","null 1 2","0 1 1"],"answer":1,"explanation":"put returns the previous value for the key, or null if there was none. The second put replaces 1 with 2 and returns 1. The key is the same, so the size stays 1.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-oops-cpp-java-41", "question": "What does sizeof print for an empty class in C++?\n```cpp\nclass Empty { };\nint main() { cout << sizeof(Empty); }\n```", "options": ["0", "8", "1", "4"], "answer": 2, "explanation": "C++ requires distinct objects to have distinct addresses, so even an empty class occupies at least 1 byte. (As a base class it may take 0 bytes thanks to the empty-base optimisation.)", "difficulty": "hard", "source": "Wipro · Capgemini pattern"},
  {"id":"cs-oops-cpp-java-42","question":"What is printed?\n```java\nSystem.out.print(\"apple\".compareTo(\"apricot\") + \" \"\n    + \"app\".compareTo(\"apple\") + \" \"\n    + \"b\".compareTo(\"a\"));\n```","options":["-1 -2 1","-1 -1 1","-2 -1 1","-2 -2 1"],"answer":3,"explanation":"compareTo returns the difference of the first differing characters: 'p' - 'r' = -2. If one string is a prefix of the other, it returns the length difference: 3 - 5 = -2. 'b' - 'a' = 1. It is not limited to -1, 0, 1.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-43","question":"What is printed?\n```java\nclass P {\n    static void sm() { System.out.print(\"P\"); }\n    void im()        { System.out.print(\"P\"); }\n}\nclass C extends P {\n    static void sm() { System.out.print(\"C\"); }\n    void im()        { System.out.print(\"C\"); }\n}\n// in main:\nP p = new C();\np.sm();\np.im();\n```","options":["PC","CC","PP","CP"],"answer":0,"explanation":"Static methods are not overridden, only hidden: p.sm() is bound at compile time by the declared type P. Instance methods are dispatched on the actual object, a C. So PC.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-44","question":"What is printed?\n```java\nclass P {\n    int x = 10;\n    int getX() { return x; }\n}\nclass C extends P {\n    int x = 20;\n    int getX() { return x; }\n}\n// in main:\nP p = new C();\nSystem.out.print(p.x + \" \" + p.getX());\n```","options":["20 20","10 20","10 10","20 10"],"answer":1,"explanation":"Fields are not polymorphic: p.x uses the declared type P and reads P's x, 10. The method call is dynamically dispatched to C.getX, which reads C's x, 20.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-45", "question": "What is printed (default JVM settings)?\n```java\nInteger x = 127, y = 127;\nInteger p = 128, q = 128;\nSystem.out.print((x == y) + \" \" + (p == q));\n```", "options": ["true true", "false false", "true false", "false true"], "answer": 2, "explanation": "Autoboxing uses Integer.valueOf, which returns cached objects for -128 to 127, so x and y are the same object. 128 is outside the cache, so p and q are different objects and == compares references. Use equals for wrapper values.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-46","question":"What is printed?\n```java\n// static methods of the main class:\nstatic void f(Object o) { System.out.print(\"Object\"); }\nstatic void f(String s) { System.out.print(\"String\"); }\n// in main:\nf(null);\n```","options":["NullPointerException at run time","Compilation error: ambiguous call","Object","String"],"answer":3,"explanation":"null fits both parameter types, and Java picks the most specific applicable overload. String is a subclass of Object, so f(String) wins. Adding an unrelated overload such as f(Integer) would make the call ambiguous.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-47","question":"What is printed?\n```java\n// static methods of the main class:\nstatic void f(long x)    { System.out.print(\"long\"); }\nstatic void f(Integer x) { System.out.print(\"Integer\"); }\nstatic void f(Object x)  { System.out.print(\"Object\"); }\nstatic void f(int... x)  { System.out.print(\"varargs\"); }\n// in main:\nf(5);\n```","options":["long","varargs","Integer","Object"],"answer":0,"explanation":"Java resolves overloads in phases: first by widening only (int to long), then with boxing, then with varargs. f(long) is found in phase one, so boxing to Integer or Object is never considered.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-48","question":"What is printed?\n```java\nclass P {\n    P() { show(); }\n    void show() { System.out.print(\"P \"); }\n}\nclass C extends P {\n    int x = 10;\n    void show() { System.out.print(\"C\" + x + \" \"); }\n}\n// in main:\nnew C().show();\n```","options":["P C10","C0 C10","C10 C10","P C0"],"answer":1,"explanation":"P's constructor runs before C's field initialisers, but the call show() is still dispatched to C.show, which sees x at its default value 0. After construction x is 10. Calling overridable methods from a constructor is a known trap.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-49","question":"What is printed?\n```java\nclass T {\n    static { System.out.print(\"S\"); }\n    { System.out.print(\"I\"); }\n    T() { System.out.print(\"C\"); }\n}\n// in main:\nnew T();\nnew T();\n```","options":["ICSIC","SCIC","SICIC","SICSIC"],"answer":2,"explanation":"The static block runs once, when the class is first initialised. For every object the instance initialiser block runs before the constructor body. So S, then IC twice.","difficulty":"very-hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-oops-cpp-java-50","question":"What is printed?\n```java\n// static methods of the main class:\nstatic int f() {\n    int x = 1;\n    try { return x; }\n    finally { x = 5; }\n}\nstatic int g() {\n    try { return 1; }\n    finally { return 2; }\n}\n// in main:\nSystem.out.print(f() + \" \" + g());\n```","options":["5 1","1 1","5 2","1 2"],"answer":3,"explanation":"In f, return x saves the value 1 before finally runs; changing x afterwards does not alter the saved int. In g, a return inside finally replaces the pending return 1, so g returns 2.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-51","question":"What is printed?\n```java\nSystem.out.print(1 + 2 + \"3\" + 4 + 5);\n```","options":["3345","339","15","12345"],"answer":0,"explanation":"+ groups left to right: 1 + 2 = 3 (numbers), then 3 + \"3\" = \"33\" (a String), and from then on every + concatenates: \"334\", \"3345\".","difficulty":"very-hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-oops-cpp-java-52","question":"What is printed?\n```java\n// static methods of the main class:\nstatic void change(StringBuilder sb) {\n    sb.append(\"X\");\n    sb = new StringBuilder(\"Y\");\n    sb.append(\"Z\");\n}\n// in main:\nStringBuilder s = new StringBuilder(\"A\");\nchange(s);\nSystem.out.print(s);\n```","options":["YZ","AX","AXYZ","A"],"answer":1,"explanation":"Java passes the reference by value. append(\"X\") changes the shared object, so the caller sees AX. Reassigning sb only changes the local copy of the reference; the later YZ object is lost when the method returns.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-53","question":"What is printed?\n```java\nList<Integer> l = new ArrayList<>(List.of(1, 2, 3));\nl.remove(1);\nSystem.out.print(l + \" \");\nl.remove(Integer.valueOf(1));\nSystem.out.print(l);\n```","options":["[2, 3] [3]","[2, 3] [2, 3]","[1, 3] [3]","[1, 3] [1, 3]"],"answer":2,"explanation":"remove(1) with an int literal matches remove(int index), removing the element at index 1 (the value 2). remove(Integer.valueOf(1)) matches remove(Object) and removes the value 1.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-54","question":"What is printed?\n```java\nList<Integer> list = new ArrayList<>(List.of(1, 2, 3));\nfor (Integer i : list)\n    if (i == 2) list.remove(i);\nSystem.out.print(list);\n```","options":["[1, 2]","ConcurrentModificationException is thrown","[2, 3]","[1, 3]"],"answer":3,"explanation":"list.remove(i) with an Integer removes the value 2. The size drops to 2 while the iterator's cursor is already 2, so hasNext() returns false and the loop ends before next() can detect the change. Removing any other element here would throw ConcurrentModificationException.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-55", "question": "What happens with this C++ code?\n```cpp\nvoid f(int a, int b = 0) { cout << \"two\"; }\nvoid f(int a)            { cout << \"one\"; }\nint main() { f(5); }\n```", "options": ["Compilation error: the call f(5) is ambiguous", "Prints two", "Compilation error at the second declaration", "Prints one"], "answer": 0, "explanation": "Both declarations are legal overloads, and f(5, 6) would work. But f(5) matches f(int) and f(int, int = 0) equally well, so the call is ambiguous and the program does not compile.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-56","question":"What is printed?\n```cpp\nstruct Base    { virtual void show() { cout << \"Base \"; } };\nstruct Derived : Base { void show() override { cout << \"Derived \"; } };\nint main() {\n    Derived d;\n    Base b = d;\n    Base &r = d;\n    b.show();\n    r.show();\n}\n```","options":["Derived Base","Base Derived","Base Base","Derived Derived"],"answer":1,"explanation":"Base b = d copies only the Base part (object slicing), so b really is a Base and calls Base::show. A reference keeps the dynamic type, so r.show() dispatches to Derived::show.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-57", "question": "What is printed?\n```cpp\nclass Base {\npublic:\n    Base() { hello(); }\n    virtual void hello() { cout << \"B\"; }\n};\nclass Derived : public Base {\npublic:\n    Derived() { hello(); }\n    void hello() override { cout << \"D\"; }\n};\nint main() { Derived d; }\n```", "options": ["D", "DD", "BD", "BB"], "answer": 2, "explanation": "While Base's constructor runs, the object is still a Base, so virtual calls resolve to Base::hello (B). In Derived's constructor the dynamic type is Derived (D). Java behaves differently: it would dispatch to the derived override even from the base constructor.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-58","question":"What is printed?\n```cpp\nstruct A { A() { cout << \"A\"; } };\nstruct B : virtual A { B() { cout << \"B\"; } };\nstruct C : virtual A { C() { cout << \"C\"; } };\nstruct D : B, C { D() { cout << \"D\"; } };\nint main() { D d; }\n```","options":["ABACD","DCBA","ABCD","BCAD"],"answer":2,"explanation":"With virtual inheritance D contains one shared A, constructed first by the most-derived class, then the bases in declaration order B, C, then D: ABCD. Without virtual each path would build its own A: ABACD.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-59", "question": "How many of these statements about C++ friend functions are correct?\n(i) A friend function can access the private members of the class that declares it a friend.\n(ii) Friendship is inherited by classes derived from that class.\n(iii) Friendship is neither symmetric nor transitive.\n(iv) A friend function is called with the object.function() member syntax.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(i) true. (ii) false: a friend of Base gets no access to what Derived adds. (iii) true: A being a friend of B does not make B a friend of A, nor friends of friends. (iv) false: it is not a member, so it is called like an ordinary function. So two.", "difficulty": "very-hard", "source": "Statement-count style · Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-60","question":"Interfaces A and B both declare default void hello(). What happens with class C implements A, B { } ?","options":["B's hello is used because it is listed last","It compiles, and calling hello() throws an exception","A's hello is used because A is listed first","Compilation error: C must override hello() (it may call A.super.hello() inside)"],"answer":3,"explanation":"When two interfaces supply the same default method, Java refuses to guess. C must override hello(), and may delegate to one of them with A.super.hello() or B.super.hello().","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-61", "question": "How many of these are correct in Java (8 or later)?\n(i) An abstract class can have a constructor.\n(ii) An interface can declare instance (non-static) fields.\n(iii) A class can extend only one class but implement many interfaces.\n(iv) An interface can have static methods with a body.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i) true: it runs when a subclass object is created. (ii) false: interface fields are always public static final. (iii) true. (iv) true since Java 8. So three.", "difficulty": "very-hard", "source": "Statement-count style · Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-62","question":"What is printed?\n```java\n// static methods of the main class:\nstatic void f() {\n    try {\n        System.out.print(\"1\");\n        throw new IllegalStateException();\n    } catch (IllegalArgumentException e) {\n        System.out.print(\"2\");\n    } finally {\n        System.out.print(\"3\");\n    }\n    System.out.print(\"4\");\n}\n// in main:\ntry { f(); }\ncatch (RuntimeException e) { System.out.print(\"5\"); }\nSystem.out.print(\"6\");\n```","options":["1356","1346","12346","136"],"answer":0,"explanation":"f prints 1 and throws IllegalStateException, which the IllegalArgumentException handler does not match. finally still prints 3, the exception leaves f so 4 is skipped, main's RuntimeException handler prints 5, and then 6.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-63","question":"What is printed?\n```java\nString s1 = \"Java\";\nString s2 = \"Ja\" + \"va\";\nString part = \"Ja\";\nString s3 = part + \"va\";\nSystem.out.print((s1 == s3) + \" \" + (s1 == s2) + \" \" + (s1 == s3.intern()));\n```","options":["false false true","false true true","false false false","true true true"],"answer":1,"explanation":"\"Ja\" + \"va\" is a compile-time constant, folded into the pooled literal \"Java\", so s1 == s2. part is a variable, so part + \"va\" builds a new object at run time (false). intern() returns the pooled copy, which is s1.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-64","question":"What is printed?\n```java\nclass P {\n    private void f() { System.out.print(\"P\"); }\n    void g() { f(); }\n}\nclass C extends P {\n    void f() { System.out.print(\"C\"); }\n}\n// in main:\nnew C().g();\n```","options":["C","Compilation error","P","PC"],"answer":2,"explanation":"Private methods are not inherited and cannot be overridden; C.f is an unrelated new method. Inside P, the call f() is bound to P's private f at compile time, so P prints.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-65", "question": "What is printed?\n```java\nclass Animal { String speak() { return \"animal\"; } }\nclass Dog extends Animal { String speak() { return \"dog\"; } }\n// static methods of the main class:\nstatic String m(Animal a) { return \"A\"; }\nstatic String m(Dog d)    { return \"D\"; }\n// in main:\nAnimal a = new Dog();\nSystem.out.print(m(a) + \"-\" + a.speak());\n```", "options": ["D-dog", "A-animal", "D-animal", "A-dog"], "answer": 3, "explanation": "Overload choice uses the compile-time type of the argument, Animal, so m(Animal) runs: A. The overridden speak is chosen at run time from the real object, a Dog: dog.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-66","question":"What is printed?\n```java\nclass P {\n    int id;\n    P(int id) { this.id = id; }\n    @Override\n    public boolean equals(Object o) {\n        return o instanceof P && ((P) o).id == id;\n    }\n}\n// in main:\nSet<P> s = new HashSet<>();\ns.add(new P(1));\ns.add(new P(1));\nSystem.out.print(s.size() + \" \" + new P(1).equals(new P(1)));\n```","options":["2 true","1 true","2 false","1 false"],"answer":0,"explanation":"equals says the objects are equal, but hashCode was not overridden, so each object keeps its identity hash and lands in a different bucket; HashSet never compares them with equals. Overriding equals requires overriding hashCode.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-67","question":"What is printed?\n```java\nSystem.out.print(5.0 / 0 + \" \");\nSystem.out.print(0.0 / 0 + \" \");\ntry { System.out.print(5 / 0); }\ncatch (ArithmeticException e) { System.out.print(\"AE\"); }\n```","options":["AE AE AE","Infinity NaN AE","Infinity NaN Infinity","Infinity 0 AE"],"answer":1,"explanation":"Floating-point division follows IEEE 754: 5.0 / 0 is Infinity and 0.0 / 0 is NaN, with no exception. Integer division by zero throws ArithmeticException.","difficulty":"very-hard","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-oops-cpp-java-68", "question": "What is printed?\n```cpp\nstruct R { int v = 0; R& inc() { v++; return *this; } };\nstruct V { int v = 0; V  inc() { v++; return *this; } };\nint main() {\n    R r; V w;\n    r.inc().inc().inc();\n    w.inc().inc().inc();\n    cout << r.v << \" \" << w.v;\n}\n```", "options": ["1 1", "3 3", "3 1", "1 3"], "answer": 2, "explanation": "R::inc returns a reference, so each chained call works on r itself: 3. V::inc returns a copy, so only the first call touches w (v = 1); the next two increment temporary copies.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-69","question":"What is printed?\n```cpp\nint a = 5;\nint &r = a;\nr = 10;\nint b = 20;\nr = b;\nb = 30;\ncout << a << \" \" << r;\n```","options":["30 30","20 30","10 30","20 20"],"answer":3,"explanation":"A reference is bound once, at initialisation, and cannot be re-seated. r = b copies the value 20 into a; it does not make r refer to b. So later b = 30 has no effect: a and r are both 20.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-70", "question": "What is printed?\n```java\nclass R implements AutoCloseable {\n    String n;\n    R(String n) { this.n = n; System.out.print(\"o\" + n + \" \"); }\n    public void close() { System.out.print(\"c\" + n + \" \"); }\n}\n// in main:\ntry (R a = new R(\"A\"); R b = new R(\"B\")) {\n    System.out.print(\"body \");\n    throw new RuntimeException();\n} catch (RuntimeException e) {\n    System.out.print(\"catch \");\n} finally {\n    System.out.print(\"fin\");\n}\n```", "options": ["oA oB body catch cB cA fin", "oA oB body catch fin cB cA", "oA oB body cB cA catch fin", "oA oB body cA cB catch fin"], "answer": 2, "explanation": "Resources open in order and close in reverse order (B then A), and they are closed before the catch block runs. finally runs last.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-71","question":"What is printed?\n```cpp\nstruct B {\n    virtual void f(int x = 1) { cout << \"B\" << x; }\n};\nstruct D : B {\n    void f(int x = 2) override { cout << \"D\" << x; }\n};\nint main() {\n    B *p = new D;\n    p->f();\n}\n```","options":["D1","D2","B1","B2"],"answer":0,"explanation":"The function body is chosen at run time (D::f), but default arguments are filled in at compile time from the static type B*, so x = 1. Never give an override a different default argument.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-72", "question": "What is printed?\n```java\nclass T {\n    static String hi() { return \"hi\"; }\n}\n// in main:\nT t = null;\nSystem.out.print(t.hi());\n```", "options": ["NullPointerException", "hi", "null", "Compilation error"], "answer": 1, "explanation": "A static method call through a reference is compiled as T.hi(); the reference is never dereferenced, so its being null does not matter. (Calling an instance method on null would throw NullPointerException.)", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-73","question":"What is printed?\n```java\nchar x = 'A';\nint i = 0;\nSystem.out.print(true ? 1 : 2.0);\nSystem.out.print(\" \");\nSystem.out.print(true ? x : i);\n```","options":["1.0 A","1 A","1.0 65","1 65"],"answer":2,"explanation":"The two branches of ?: are brought to one type. int and double give double, so 1 prints as 1.0. char and an int variable give int, so 'A' prints as 65 (only an int constant that fits in char would keep the type char).","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-74","question":"What is printed?\n```cpp\nstruct B {\n    void f(int)    { cout << \"Bi\"; }\n    void f(double) { cout << \"Bd\"; }\n};\nstruct D : B {\n    void f(double) { cout << \"Dd\"; }\n};\nint main() {\n    D d;\n    d.f(5);\n}\n```","options":["Bd","Compilation error: ambiguous call","Bi","Dd"],"answer":3,"explanation":"Declaring any f in D hides every f inherited from B (name hiding), so only D::f(double) is considered and 5 is converted to 5.0: Dd. Adding using B::f; inside D would bring B::f(int) back and print Bi.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-oops-cpp-java-75", "question": "How many of these are correct about C++ virtual functions on a typical implementation?\n(i) Each class with virtual functions has a table of function pointers (vtable).\n(ii) Each object of such a class carries a hidden pointer to its class's vtable.\n(iii) A constructor can be declared virtual.\n(iv) A static member function can be virtual.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(i) and (ii) describe the usual vtable/vptr mechanism, which is why such objects grow by one pointer. (iii) false: constructors cannot be virtual (destructors can). (iv) false: static functions have no this object to dispatch on. So two.", "difficulty": "very-hard", "source": "Statement-count style · Product-company MCQ pattern"},
  {"id":"cs-oops-cpp-java-76","question":"A method call such as shape.area() runs different code depending on whether shape refers to a Circle or a Square object at run time. Which OOP feature is this?","options":["Encapsulation","Compile-time polymorphism (method overloading)","Runtime polymorphism (dynamic dispatch through overriding)","Data abstraction through access specifiers"],"answer":2,"explanation":"Choosing the overridden method from the object’s actual class at run time is runtime polymorphism. Overloading is resolved at compile time from the argument types, and encapsulation is about bundling and hiding data.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-oops-cpp-java-77","question":"A Java class declares only the constructor Account(String id) and no other constructor. What happens with the statement new Account()?","options":["The compiler adds a default no-argument constructor automatically","It compiles, and id is set to null","It throws a NullPointerException at run time","Compilation error: no no-argument constructor exists"],"answer":3,"explanation":"The compiler supplies a default constructor only when a class declares NO constructors. Once Account(String) exists, new Account() does not compile unless a no-arg constructor is written.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-oops-cpp-java-78","question":"What is printed?\n```java\nint x = 5;\nx = x++ + ++x;\nSystem.out.print(x);\n```","options":["12","11","13","10"],"answer":0,"explanation":"Java evaluates left to right: x++ yields 5 (x becomes 6), then ++x makes x 7 and yields 7. 5 + 7 = 12 is assigned to x, overwriting the increments.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-oops-cpp-java-79","question":"What is printed?\n```cpp\nclass A {\npublic:\n    int x;\n    A(int v) : x(v) {}\n};\nint main() {\n    A a(5);\n    A b = a;\n    b.x = 9;\n    cout << a.x << b.x;\n}\n```","options":["99","59","55","95"],"answer":1,"explanation":"A b = a copies the object (memberwise, by the implicit copy constructor); b is independent of a. Changing b.x leaves a.x at 5. 99 is what Java-style reference semantics would give, but C++ objects are values.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-oops-cpp-java-80","question":"Which line fails to compile?\n```java\nabstract class Shape { abstract double area(); }\nclass Sq extends Shape { double area() { return 4; } }\n// in main:\nShape s1 = new Sq();          // L1\nShape s2 = new Shape();       // L2\nShape[] arr = new Shape[3];   // L3\n```","options":["L1","L3","L2","None of them"],"answer":2,"explanation":"An abstract class cannot be instantiated, so new Shape() fails. L1 uses a concrete subclass through a base reference, and L3 only creates an array of null references of type Shape, which is allowed.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-oops-cpp-java-81","question":"What is printed?\n```java\nclass K {\n    K() { this(5); System.out.print(\"A\"); }\n    K(int x) { System.out.print(\"B\" + x); }\n}\n// in main:\nnew K();\n```","options":["AB5","A","B5","B5A"],"answer":3,"explanation":"this(5) must run first and calls K(int), printing B5; control then returns to the rest of K(), printing A.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-oops-cpp-java-82","question":"Which line fails to compile?\n```java\nfinal int[] arr = {1, 2, 3};\narr[0] = 10;          // L1\narr = new int[3];      // L2\nSystem.out.print(arr[0]); // L3\n```","options":["L2","L1","L3","Both L1 and L2"],"answer":0,"explanation":"final fixes the reference, not the object: the array’s contents can change (L1 is fine), but arr cannot be pointed at a new array (L2 fails).","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-oops-cpp-java-83","question":"What is printed?\n```java\nclass P {\n    static int c = 0;\n    P() { c++; }\n}\nclass Q extends P {\n    Q() { c += 10; }\n}\n// in main:\nnew P(); new Q(); new Q();\nSystem.out.print(P.c);\n```","options":["21","23","3","12"],"answer":1,"explanation":"c is one shared static field. new P() → 1. Each new Q() first runs P() through the implicit super() (+1) and then its own body (+10): 1 + 11 + 11 = 23. 21 forgets the implicit super() call.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-oops-cpp-java-84","question":"What is printed?\n```java\nclass A {\n    int x = 10;\n    A() { x = 20; }\n    { x = 30; }\n}\n// in main:\nSystem.out.print(new A().x);\n```","options":["30","10","20","Compilation error"],"answer":2,"explanation":"Field initialisers and instance initialiser blocks run in textual order (x = 10, then x = 30) right after super(), and only then does the rest of the constructor body run (x = 20). The block’s position after the constructor in the source does not matter.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-oops-cpp-java-85","question":"What is printed?\n```java\ninterface I { default String who() { return \"I\"; } }\nclass P { public String who() { return \"P\"; } }\nclass C extends P implements I { }\n// in main:\nSystem.out.print(new C().who());\n```","options":["I","Compilation error: conflicting who()","PI","P"],"answer":3,"explanation":"Rule: “class wins”. A method inherited from a superclass takes priority over an interface default method with the same signature, so there is no conflict and P’s version runs. A conflict error arises only between two interface defaults.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-oops-cpp-java-86","question":"What is printed?\n```java\nStringBuilder a = new StringBuilder(\"hi\");\nStringBuilder b = new StringBuilder(\"hi\");\nSystem.out.print(a.equals(b) + \" \" + a.toString().equals(b.toString()));\n```","options":["false true","true true","false false","true false"],"answer":0,"explanation":"StringBuilder does not override equals, so it inherits Object.equals, which compares references: two different objects → false. Converting to String uses String.equals, which compares content → true.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-oops-cpp-java-87","question":"What happens when this Java code is compiled and run?\n```java\nObject o = new ArrayList<String>();\nList<String> l = (List<String>) o;\nString s = (String) o;\nSystem.out.print(\"done\");\n```","options":["Compilation error at the third line","It compiles; a ClassCastException is thrown at the third line","It prints done","ClassCastException at the second line"],"answer":1,"explanation":"Casting from Object to String is a legal downcast, so it compiles; at run time the object is an ArrayList, not a String, so the cast throws ClassCastException. The cast to List<String> succeeds (it only gives an unchecked warning).","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-oops-cpp-java-88","question":"What is printed?\n```cpp\nstruct A {\n    A()                     { cout << \"D\"; }\n    A(const A&)             { cout << \"C\"; }\n    A& operator=(const A&)  { cout << \"=\"; return *this; }\n};\nint main() {\n    A a;\n    A b = a;\n    A c;\n    c = a;\n}\n```","options":["D=D=","DCDC","DCD=","DDD="],"answer":2,"explanation":"A b = a initialises a new object, so it calls the copy constructor (C), despite the = sign. c = a assigns to an already constructed object, so it calls operator= (=). Output: D, C, D, =.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-oops-cpp-java-89","question":"What is printed?\n```java\nString s = \"b\";\nswitch (s) {\n    case \"a\": System.out.print(\"A\");\n    case \"b\": System.out.print(\"B\");\n    case \"c\": System.out.print(\"C\"); break;\n    default:  System.out.print(\"D\");\n}\n```","options":["B","BCD","D","BC"],"answer":3,"explanation":"The switch jumps to case \"b\" and, with no break, falls through into case \"c\", printing C, then stops at its break. default is never reached.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-oops-cpp-java-90","question":"What happens when this Java code is compiled?\n```java\ntry {\n    FileReader r = new FileReader(\"a.txt\");\n} catch (Exception e) {\n    System.out.print(\"E\");\n} catch (IOException e) {\n    System.out.print(\"IO\");\n}\n```","options":["Compilation error: the IOException catch block is unreachable","It compiles; IO is printed if the file is missing","It compiles; E is printed if the file is missing","It compiles with only a warning"],"answer":0,"explanation":"Catch blocks are tried in order, and Exception already catches every IOException, so the second block can never run. Java treats this as an error; the more specific catch must come first.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-oops-cpp-java-91","question":"This class is meant to be immutable. What change is still needed?\n```java\npublic final class Team {\n    private final List<String> members;\n    public Team(List<String> m) { members = m; }\n    public List<String> getMembers() { return members; }\n}\n```","options":["Nothing; final class plus private final fields make it immutable","Copy the list in the constructor and return an unmodifiable view or copy from the getter","Make the getter method final","Mark members as static"],"answer":1,"explanation":"final stops reassignment of the field, not changes to the list. The caller still holds the list passed in, and getMembers() exposes the internal list, so either side can change it. Defensive copies (e.g. List.copyOf(m)) fix both leaks.","difficulty":"very-hard","source":"Product-company interview pattern"},
  {"id":"cs-oops-cpp-java-92","question":"What is printed?\n```cpp\nstruct V {\n    int x;\n    V(int a) : x(a) {}\n    V operator+(const V& o) const { return V(x + o.x * 2); }\n};\nint main() {\n    V a(1), b(2), c(3);\n    cout << (a + b + c).x;\n}\n```","options":["12","9","11","13"],"answer":2,"explanation":"+ is left-associative: (a + b) = V(1 + 2 × 2) = V(5); then V(5) + c = V(5 + 3 × 2) = V(11). The operator is not symmetric, so the grouping matters; evaluating a + (b + c) would give 1 + 8 × 2 = 17.","difficulty":"very-hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-oops-cpp-java-93","question":"What is printed?\n```java\nclass A {\n    void m(A a) { System.out.print(\"AA\"); }\n}\nclass B extends A {\n    void m(A a) { System.out.print(\"BA\"); }\n    void m(B b) { System.out.print(\"BB\"); }\n}\n// in main:\nA x = new B();\nB y = new B();\nx.m(y);\n```","options":["BB","AA","Compilation error: ambiguous call","BA"],"answer":3,"explanation":"Overload choice happens at compile time using the static type of x (A), which has only m(A), so the signature m(A) is chosen. At run time the object is a B, which overrides m(A), so BA prints. m(B) is a separate overload that A’s type never sees.","difficulty":"very-hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-oops-cpp-java-94","question":"Class P is in package a and declares protected int x. Class C is in package b and extends P. Inside an instance method of C, which of these statements fails to compile?\n(1) x = 1;\n(2) this.x = 1;\n(3) new P().x = 1;","options":["Only (3)","Only (1) and (2)","All three","None of them"],"answer":0,"explanation":"Outside its package, a protected member can be accessed by a subclass only through references of the subclass type (or its own subtypes). x and this.x are accessed via C, so they compile; new P().x goes through a plain P reference, which is not allowed.","difficulty":"very-hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-oops-cpp-java-95","question":"What happens when this Java class is compiled?\n```java\nclass Util {\n    static void f(List<String> l)  { }\n    static void f(List<Integer> l) { }\n}\n```","options":["It compiles; the call is chosen by the element type","Compilation error: both methods have the same erasure","It compiles with an unchecked warning only","It compiles, but calling f throws an exception at run time"],"answer":1,"explanation":"Generic type arguments are erased at compile time, so both methods become f(List) in the bytecode. Two methods with the same erased signature clash, and the compiler rejects the class.","difficulty":"very-hard","source":"Product-company interview pattern"},
  {"id":"cs-oops-cpp-java-96","question":"How many of the following statements about equals() and hashCode() in Java are correct?\n(i) If a.equals(b) is true, a.hashCode() must equal b.hashCode().\n(ii) If a.hashCode() == b.hashCode(), then a.equals(b) must be true.\n(iii) Overriding equals() without overriding hashCode() can make a HashSet keep two “equal” objects.\n(iv) Object’s default equals() compares references.","options":["1","2","3","4"],"answer":2,"explanation":"(i), (iii) and (iv) are correct. (ii) is false: different objects may collide on the same hash code. (iii) happens because HashSet first looks in the bucket chosen by hashCode, so equal objects with different hash codes land in different buckets.","difficulty":"very-hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-oops-cpp-java-97","question":"On a typical 64-bit compiler (8-byte pointers, 4-byte int, natural alignment), what does sizeof(P) print?\n```cpp\nclass P {\n    int id;\npublic:\n    virtual void show() {}\n};\n```","options":["4","12","8","16"],"answer":3,"explanation":"A class with a virtual function gets a hidden vtable pointer (8 bytes). Add the 4-byte int and pad to a multiple of the 8-byte alignment: 8 + 4 + 4 = 16. 12 forgets padding; 4 ignores the vptr. (The exact value is implementation-defined, but this is the common layout.)","difficulty":"very-hard","source":"Wipro · Cognizant technical pattern"},
];

